    "  `scipy` is imported only when a correction actually runs), and hands back the",
    "  original y values as `connector_y` when connectors are on, so the exported",
    "  figure can draw the original→corrected connector layer too;",
    "- a corrected figure is **force-coloured by line**, exactly as the on-screen",
    "  static path forces it under correction (the surface-parity review caught this",
