    "  (same keys as the 💾 Save & restore config, ENG-23) plus the **effective**",
    "  `coloring.color_by_line`, so the manifest says which correction produced the",
    "  batch and how it was coloured.",
    "",
    "**What's left.** Nothing. The deliberate asymmetry was **kept**: the exported",
    "**tables** (fixations, measures, mega-table) stay uncorrected — correction is a",
    "view, not a rewrite of the data — and",
