   "read at *call time*, default **off** — behind `experimental_features_enabled()`",
   "plus the two named readers `drift_correction_enabled()` /",
   "`similarity_enabled()` every surface consults. **Drift correction** is gone",
   "from: the rail selectbox + connectors checkbox; the 📐 Line assignment subtab",
   "(the tab list is now built as a *list*, so the tab count is a function of the",
   "flag, and `tabs.SUBTAB_*` became named constants that `tests/conftest.py`",
   "imports rather than repeating); the deep link and the saved config",
   "(`_GATED_URL_PARAMS` — neither read nor emitted); the export manifest's",
   "`coloring.drift_correction` / `drift_connectors` keys; `render",
   "--drift-correction` (the flags are not *added* to the parser, so `--help`",
   "doesn't advertise them and passing one is an ordinary argparse error, while",
   "`viz.set_defaults` keeps `args.drift_correction` present for downstream",
   "branches); the FAQ entry and the Carr et al. citation line; and the docs",
   "(README, AGENTS, `docs/architecture.md`, `docs/cli.md`, `docs/agents.md`,",
   "`docs/guides/scanpath-visualization.md`, `docs/tutorials/line-assignment.md`).",
   "**The resolve happens once**, in `_collect_viz_settings`, which reports",
