   "cap kept a *ranked* grid readable; nothing is ranked now) while still stating",
   "the cap in the caption. `_GEN_MAX_SCORE` is a *scoring* budget, so it no",
   "longer truncates when nothing is scored.",
   "",
   "**Two deliberate asymmetries.** (a) Links and saved configs are ignored",
   "**silently**, per call 3 — but the **headless API raises**, naming the env var:",
