   "(c) the API raising rather than ignoring; (d) whether any *other* half-wired",
   "surface should join the gate.",
   "",
   "**Background (technical) — the calls, settled 2026-08-12.** Six questions were open;",
   "all six are answered, so implementation is unblocked:",
   "",
   "1. **Every surface** — UI, deep link, export, CLI, headless API, docs and README. Not a",
