   "- **📐 Line assignment subtab** — `tab_align` in the seven-tab `st.tabs` call keyed",
   "  `single_subtab`, [`tabs.py:4190`](scanpath_studio/tabs.py:4190).",
   "- **Render-time apply** — `tabs._drift_corrected` ([`tabs.py:775`](scanpath_studio/tabs.py:775)),",
   "  called from the static-figure path ([`tabs.py:3887`](scanpath_studio/tabs.py:3887)).",
   "- **Deep link / Share** — `_parse_align_algorithm`",
   "  ([`url_state.py:146`](scanpath_studio/url_state.py:146)) plus the `align_algorithm` /",
   "  `align_connectors` params, and the `coloring.drift_correction` key in 💾 Save & restore",
   "  (**ENG-23**). These are a wire format pinned by `tests/test_session_key_contract.py`.",
   "- **Export** — per-trial correction inside the bulk loop",
   "  ([`export.py:589`](scanpath_studio/export.py:589)) and the `drift_correction` /",
   "  `drift_connectors` entries in the exported settings JSON",
   "  ([`export.py:667`](scanpath_studio/export.py:667)).",
   "- **CLI** — `render --drift-correction`, validated against `alignment.ALGORITHMS`",
   "  ([`cli.py:44`](scanpath_studio/cli.py:44)).",
   "- **Headless API** — the drift parameter on `api.plot_scanpath`",
   "  ([`api.py:1130`](scanpath_studio/api.py:1130)) and `api.alignment_sensitivity`",
   "  ([`api.py:714`](scanpath_studio/api.py:714)), both re-exported from `__init__.py`.",
   "- **Illustration disclosure** — a non-`Off` algorithm counts as a geometry-changing view",
   "  ([`illustration.py:23`](scanpath_studio/illustration.py:23)).",
   "- **Guidance & docs** — the \"What does drift correction do?\" FAQ entry and the Carr et al.",
   "  citation line ([`tour.py:1328`](scanpath_studio/tour.py:1328),",
   "  [`:1368`](scanpath_studio/tour.py:1368)), `docs/tutorials/line-assignment.md`, the",
   "  Scanpath Visualization row in `README.md`, and the `tabs.py` module map in `AGENTS.md`.",
   "- **Tests** — `tests/test_share_drift.py`, `tests/test_alignment.py`,",
   "  `tests/test_apptest.py` (the subtab + `Attach` smoke), `tests/test_mode_parity.py`,",
   "  `tests/test_export.py`, and `conftest.SUBTAB_LINE_ASSIGNMENT`. Whichever way the",
   "  decisions land, these need to assert the *new* behaviour rather than be deleted.",
   "",
   "**Background (technical) — NLD similarity.** All three blocks live inside one function,",
   "`tabs.render_multiple_comparison_tab` (the **Generations** panel under 🔬 Comparisons),",
   "and all three hang off the single `compute_similarity_table` call at",
   "[`tabs.py:6794`](scanpath_studio/tabs.py:6794):",
   "",
   "- **Other scanpaths ranking** — the `ranked` sort by NLD",
   "  ([`tabs.py:6801`](scanpath_studio/tabs.py:6801)) picks which `_GEN_MAX_PANELS` (24)",
   "  panels are drawn, the `rank_note` caption says \"ranked by NLD similarity … most",
   "  similar first\" / \"the **24 most similar** of N scored\"",
   "  ([`tabs.py:6814`](scanpath_studio/tabs.py:6814)), and each panel's caption carries",
   "  `· NLD 0.42 ·` ([`tabs.py:6856`](scanpath_studio/tabs.py:6856)). Per call 5: sort",
   "  alphabetically by the comparison-column value and raise `_GEN_MAX_PANELS`",
   "  ([`tabs.py:6489`](scanpath_studio/tabs.py:6489)) — with nothing being scored there is",
   "  no reason to keep the panel count at 24. `_GEN_MAX_SCORE = 60`",
   "  ([`tabs.py:6493`](scanpath_studio/tabs.py:6493)) and its \"the rest are not shown\"",
   "  warning ([`tabs.py:6737`](scanpath_studio/tabs.py:6737)) are a *scoring* budget and go",
   "  dead with the flag off — whatever cap survives has to be stated in the caption either",
   "  way, so the grid never silently truncates.",
   "- **Similarity to the selected scanpath** — the styled table,",
   "  [`tabs.py:6870`](scanpath_studio/tabs.py:6870) (`_style_similarity_table`,",
   "  [`tabs.py:6218`](scanpath_studio/tabs.py:6218)). This is where the three unimplemented",
   "  metrics show as *\"Not yet computed\"* placeholders",
   "  ([`similarity.py:205`](scanpath_studio/similarity.py:205) onwards, `fn=None`) — the",
   "  clearest instance of the \"not fully integrated\" smell driving this item. Per call 6",
   "  the metric picker ([`tabs.py:6201`](scanpath_studio/tabs.py:6201)) and",
   "  `_style_similarity_table` ([`tabs.py:6218`](scanpath_studio/tabs.py:6218)) go with it,",
   "  not just the table itself.",
   "- **Metric convergence** — the heading, caption, the memoized `nld_by_fixation_index` /",
   "  `nld_by_time` curves and the two `make_metric_convergence_figure` charts,",
   "  [`tabs.py:6880`](scanpath_studio/tabs.py:6880)–[`6942`](scanpath_studio/tabs.py:6942).",
   "  Its `_multi_conv_key` / `_multi_conv_fix` / `_multi_conv_time` session keys go with it.",
   "",
   "Beyond the panel, and in scope under call 6: `similarity.py` also feeds the **CMP-6**",
   "candidate ordering, which is a *second* place NLD reaches the user and must go behind the",
   "same flag. `plots.make_metric_convergence_figure`",
   "([`plots.py:5470`](scanpath_studio/plots.py:5470)) becomes unreferenced from the UI with",
   "the flag off — it stays, like `alignment.py` and `similarity.py` do; this is a gate, not",
   "a deletion. Tests to update: `tests/test_similarity.py` and whatever in",
   "`tests/test_apptest.py` asserts the Comparisons panel's contents — force the flag on for",
   "the existing assertions, and add absence checks for the default-off build.",
   "",
   "Related: **PRE-3** (shipped drift correction), **PRE-9** (its four-surface follow-up —",
