    "asserting it rendered — which is what proves the button is wired to a live",
    "payload and that serving it doesn't break the app. What is still not possible",
    "is *reading the bytes back*: `DownloadButton` exposes `label` and a `click()`",
    "trigger, no data, because the payload lives in Streamlit's media-file manager",
    "and never enters the element tree. So the `tabs.bulk_export` seam stays — but",
    "it now substitutes only the **inspection** of the zip, not its delivery. The",
