    "router's selection so the tour, the recovery cache and `_active_view` are unchanged.",
    "And **switching view now looks immediate**: Streamlit leaves the old page painted for",
    "the length of a full rerun, so clicking Corpus Analysis used to leave the scanpath",
    "sitting there; a loading bridge claims that space at once.",
    "",
