    "  reads) — and it would have to render as a popover inside that expander, since",
    "  Streamlit nests neither expander-in-expander nor popover-in-popover. On the",
    "  data-management page it is correctly scoped but further from the plot. Lean rail if",
    "  the goal is discoverability, page if the goal is \"the bar holds nothing dataset-wide\".",
