    "   Use the stable id—not the mutable row number—to synchronize a marker with its",
    "   table row. Bump the authoring JSON schema and migrate schema-1 files from",
    "   **VIZ-20** without changing their rendered result.",
    "2. Replace whitespace-only tokenization with a line-aware layout pass. Split on",
    "   explicit newlines first (including blank lines), then wrap within each source",
    "   line at the configured canvas width. Emit deterministic, 1-based `word_id` and",
    "   0-based `line_idx` values plus canonical top-left X/Y/width/height boxes.",
    "3. Put a read-only parsed-word preview directly below the stimulus input. Report the",
