    "4. Build the spatial editor over the same word boxes: click empty space to add a",
    "   fixation, click a marker to select it, drag to update X/Y, and provide delete plus",
    "   an obvious selected-marker state. Return compact edit events keyed by",
    "   `fixation_id`; do not send or replace the whole table on every pointer move.",
    "5. Keep the table authoritative for bulk/exact work. Show fixation id/index and",
    "   order explicitly; reconcile add/delete/reorder/coordinate edits through pure",
    "   reducer functions so canvas and table cannot each keep a competing copy. Reject",
    "   duplicate ids/orders with an actionable message rather than silently renumbering",
    "   unrelated rows.",
    "6. Preserve the normal downstream path: build `authored_fixations`, recompute",
    "   timestamps from the ordered durations, expose invalid/out-of-text rows, and verify",
    "   that the resulting trial still renders, computes measures, and exports exactly",
