   "title": "Rebuild the data-upload pipeline: stepper, guide that follows, honest experimental setup",
   "status": "Review",
   "note": "Implemented 2026-08-12; pending user review.",
   "date": "2026-08-12",
   "added": "2026-08-12",
   "group": "Datasets & ingestion",
   "subgroup": "",
   "archived": false,
   "request": [
    "Four things, with explicit authority to break the whole pipeline down",
    "and rebuild it. (1) Changing a field \u2014 e.g. in **Trial identifier** \u2014 collapses the",
    "step every time; keep it open. (2) The setup guide does not follow you or highlight",
    "the part it is talking about. (3) Steps that take processing time must make it",
    "obvious something is happening in the background. (4) Clear up, organize and improve",
    "the UI/UX of the whole pipeline: it is complicated for new users, currently",
    "overwhelming, and easy to miss important steps. The user may be the person who",
    "collected the data or someone merely using it, and may not have all the details to",
    "hand \u2014 so **don't assume a default that may be incorrect**. Let them make a conscious",
    "choice between finding out the real value, taking a named default, or skipping."
   ],
   "whatWasDone": [
    "All four, per [`plans/data-22-upload-pipeline-rebuild.md`](plans/data-22-upload-pipeline-rebuild.md).",
    "*(1)* A new [`wizard_shell.py`](scanpath_studio/wizard_shell.py) owns a six-step",
    "accordion (Your data \u00b7 Trials & readers \u00b7 Fixations & text \u00b7 Recording setup \u00b7 Extra",
    "fields \u00b7 Name & add) whose open flag is a **keyed `st.expander`** written only by",
    "`seed_open_step` / `go_to_step` / `continue_button` / the progress chips / the guide \u2014",
    "so an edit inside a step can no longer move it. `_wizard_step_expanded`,",
    "`_keep_wizard_step_open`, `_wizard_keep_open`, `flow[\"claimed\"]` and",
    "`_render_wizard_progress` are deleted, along with the now-dead `on_change` plumbing in",
    "`controls.column_mapping_ui`. *(2)* `_highlight_css` and `_scroll_into_view_script` are",
    "factored out of `render_spotlight_tour`; `_WIZARD_GUIDE_STEPS` now carry a `selector`",
    "(the keyed expanders give `.st-key-wiz_open_*` for free) and a `step_id`, and the",
    "card's Back/Next call `wizard_shell.go_to_step`, so the guide drives the wizard rather",
    "than narrating beside it. *(3)* `_trial_id_values`, `_distinct_id_count`, the three",
    "`propose_*_schema`, `categorize_columns` and `aggregate_char_boxes` are cached on",
    "`data.frame_fingerprint` + the mapping, each behind a labelled spinner. *(4)*",
    "`_render_data_setup` (620 lines, 16 expanders, five subsections) is rebuilt into the",
    "six step bodies; sub-blocks are popovers (expander-in-expander is forbidden). The",
    "**Recording setup** moved *after* the upload and is three `st.radio(index=None)`",
    "groups \u2014 nothing preselected \u2014 offering *I know these* / *Estimate from my data* /",
    "*Use a named default* / *Skip*, gating **Add dataset** until all three are answered."
   ],
   "whatsLeft": [
    "User review. First round of feedback (2026-08-12) is **fixed**: the",
    "step no longer closes on upload; the *jump to Recording setup* shortcut is gone (a",
    "detected mapping still has to be confirmed \u2014 detection matches column *names*, so it",
    "is confident and occasionally wrong, and a wrong mapping renders a plausible figure of",
    "the wrong thing); the hosted-demo upload-size warning is gated to hosted runs; the",
    "upload cap follows the launch (Streamlit's 200 MB default applied to any pip-installed",
    "launch outside the repo root); and the copy that explained the *old* behaviour",
    "(\"nothing collapses under you\") is rewritten for someone who never saw it. Still worth",
    "clicking: (a) the accordion in general \u2014 change a mapping twice in step 2 and confirm",
    "the step stays open; (b) the Recording-setup wording \u2014 whether the three groups and",
    "their four choices are the right questions, and whether *Estimate from my data* stating",
    "a **lower bound** reads clearly; (c) the guide's highlight/scroll on each step; (d) the",
    "step-6 review table and whether the provenance column earns its place."
   ],
   "background": [
    "The provenance model lives in",
    "[`experimental_setup.py`](scanpath_studio/experimental_setup.py) as `Provenance` +",
    "`SetupSnapshot`, unified with **CMP-8**'s per-dataset snapshot rather than built twice",
    "\u2014 both plans wanted a type in the same module and a key on the same",
    "`_wizard_finalize_payload`. Anything derived from a `SKIPPED` group (`dpi`,",
    "`px_per_degree`, pt\u2192px) resolves to `None` so callers hide it instead of computing it",
    "from a default. Provenance travels the four surfaces a recipient could be misled by:",
    "the review table + Data Inspection, a `setup_prov=screen:\u2026,geom:\u2026,text:\u2026` share param",
    "(`session_keys.SETUP_PROVENANCE_PARAM`, pinned in `test_session_key_contract.py` via a",
    "new `URL_OPTIONAL_PARAMS` set \u2014 it is emitted only when the source declares a setup,",
    "so it is not in `SHARE_QUERY_PARAMS`), the saved-config `experimental_setup` section",
    "(which already existed and simply gains `provenance`; additive, so per **ENG-11**",
    "`PLOT_CONFIG_SCHEMA` stays at 2), and bulk export's `plot_config.json`. It deliberately",
    "does **not** become a `render` flag or a builder argument: it is metadata *about*",
    "settings and changes no figure. **Verification gap worth knowing:** `AppTest` never",
    "echoes an expander's open state back \u2014 a programmatic `True` reverts on the very next",
    "*bare* rerun, with no edit involved \u2014 so the plan's headline regression test cannot",
    "pass against any implementation. It is replaced by a structural test that no step body",
    "writes a `wiz_open_*` key (the single rule the fix rests on) plus direct tests of the",
    "shell's navigation; the click-through itself is the user-review item above. Ten",
    "existing AppTests that finalized an upload immediately now answer the setup step via a",
    "shared `tests/conftest.answer_setup_step` helper. Supersedes **DATA-19**. Related:",
    "**CMP-8**, **DATA-2**, **ENG-11**, **BUG-2**.",
    "",
    "**Background \u2014 the second collapse mechanism (found in review).** Streamlit remounts a",
    "*keyed* expander at its collapsed default on the next run after its **label or icon**",
    "changes, whatever the key holds. The step's status badge was passed as `icon=`, so an",
    "upload flipping step 1 to *done* slammed it shut \u2014 the DATA-19 symptom arriving through",
    "an entirely different door, and the reason the accordion looked fixed in tests but not",
    "in the browser. What hid it: AppTest never echoes an expander's open state back, so the",
    "real bug and the test artifact fail identically. The badge now lives only on the",
    "progress chips, and `tests/test_wizard_helpers.py` pins it with a **control case** \u2014 a",
    "stable header survives the run a varying one dies on, and that difference is the bug.",
    "Also fixed in the same round: the hosted-demo upload-size warning is gated on the same",
    "loopback check as the wizard's *run locally* tip, and `constants.UPLOAD_MAX_SIZE_MB` is",
    "injected as `--server.maxUploadSize` by `cli.launch_app` \u2014 `.streamlit/config.toml` is",
    "resolved against the *launch* directory, so every pip-installed launch outside the repo",
    "root had silently been capped at Streamlit's 200 MB default."
   ]
