   "id": "BUG-25",
   "prefix": "BUG",
   "num": 25,
   "sub": "",
   "title": "saccade_amplitude conflates degrees and pixels — the bundled demo reports 1.95 under a \"px\" label",
   "status": "Review",
   "note": "",
   "date": "",
   "added": "2026-08-13",
   "group": "Bugs",
   "subgroup": "",
   "archived": false,
   "request": [
    "Not asked for \u2014 found while scoping #VAL-5, and confirmed on the",
    "bundled demo before filing. Your call on the open decision: *\"go with the option",
    "that is more straightforward. I don't want to deal with complicated or uncertain",
    "conversions.\"*"
   ],
   "whatWasDone": [
    "The straightforward option is **no conversion in either",
    "direction**, so the two quantities stop sharing a name. `saccade_amplitude` is",
    "now always **pixels** \u2014 the euclidean distance `measures.enrich_fixations`",
    "computes, or a source column of that literal name \u2014 and EyeLink's degree-valued",
    "columns normalize to their own canonical names in",
    "[`data.py`](scanpath_studio/data.py:1732):",
    "`NEXT_SAC_AMPLITUDE` \u2192 `next_saccade_amplitude_deg`,",
    "`PREVIOUS_SAC_AMPLITUDE` \u2192 `prev_saccade_amplitude_deg`. That fixes the second",
    "defect in the same edit: those two are *different saccades* (the one leaving",
    "this fixation and the one that arrived at it), so they no longer collapse into",
    "one column whose meaning depended on the export \u2014 and the column no longer",
    "shifts by one fixation relative to `progression` / `is_regression` /",
    "`angle_outgoing`, which are outgoing by construction. Both stay reachable for",
    "colour-by, hover and per-fixation filters under their own names. The bundled",
    "demo now reports `median 151 px` where it reported `1.95` under a `px` label;",
    "the 1.95 is still there, correctly labelled, as `next_saccade_amplitude_deg`.",
    "`aggregation.MEASURES[\"sacc_amp\"]`'s hard-coded `unit=\"px\"` is now *true* rather",
    "than something to fix, so it stays \u2014 and `mean_saccade_px` in the per-reader",
    "summary needs no rename for the same reason."
   ],
   "whatsLeft": [
    "Your review. One judgement call to check: this **changes what",
    "the demo's saccade-amplitude figure shows** \u2014 from ~1.95 (degrees, mislabelled)",
    "to ~151 (pixels, correctly labelled). That is the point of the fix, but it is a",
    "visible change to a published-looking number, so it is worth agreeing to",
    "deliberately. Worth clicking: Corpus Analysis \u2192 any saccade-amplitude view, and",
    "the per-reader summary's `mean_saccade_px`. Also worth deciding for later:",
    "whether the degree columns deserve their own entry in `aggregation.MEASURES`",
    "(they are currently passthrough fields, not offered as a corpus measure)."
   ],
   "background": [
    "Two source columns were mapped onto one canonical",
    "name in [`data.py:1726`](scanpath_studio/data.py:1726). EyeLink writes both in",
    "**degrees of visual angle**; when neither was present,",
    "[`measures.py`](scanpath_studio/measures.py:372) computed a euclidean distance",
    "in **pixels** instead. Nothing recorded which one you got, and",
    "[`aggregation.py:317`](scanpath_studio/aggregation.py:317) declared `unit=\"px\"`",
    "either way, so every Corpus Analysis axis said pixels. **Confirmed on the",
    "bundled demo**, which ships `NEXT_SAC_AMPLITUDE`: `min 0.13 \u00b7 median 1.95 \u00b7",
    "max 22.34` \u2014 degrees (a reading saccade is ~2\u00b0) \u2014 against a true pixel distance",
    "of `median 151 \u00b7 max 1813`. Roughly 78x apart, feeding the *same* measure.",
    "",
    "**Why not convert.** Converting either way needs",
    "`experimental_setup.pixels_per_degree`, which is `ASSUMED` on every built-in",
    "corpus \u2014 so a converted number would carry an invented monitor geometry into a",
    "scientific measure, which is exactly the \"uncertain conversion\" the brief ruled",
    "out. Keeping both quantities under honest names costs nothing and loses no data.",
    "Recorded in #VAL-5's register as `fix.saccade_amplitude`. Related: #VAL-5,",
    "#CMP-11 (the same `ASSUMED`-geometry limitation), #PRE-21."
   ]
