    "**Decision settled (2026-08-11).** Tutorials may use an explicit **Show me / Open",
    "this panel** action to navigate views and reveal controls. Guided navigation must",
    "not change loaded data, filters, annotations, or scientific/visualization",
    "settings. Related: #UX-2, #UX-12, #UX-14, #UX-23, #UX-34, #DATA-26, #UX-52.",
    "",
    "**Round 2, your two answers.** *\"Are these five outcomes still the right first",
    "set?\"* → **\"generally yes\"** — no sixth flow added; a sixth is a registry entry,",
    "not new machinery, so it stays cheap whenever one is wanted. *\"Is Explore a",
    "corpus question too thin?\"* → yes, and you named the example to build it around:",
    "*\"could show specifically average fixation duration over the whole experiment",
    "(need to switch to per-reader and then select view: per-trial trend)\"*. That is",
