    "wizard's copy of the same form stays label-above (that step *is* the form, laid out",
    "across the page, where there is no height to buy back). Playback's *Frame every* /",
    "*Max frames* pair went from two half-width columns back to full width: UX-30 put them",
    "side by side because label-above made each two rows tall, and a label-left row is one",
    "row either way — same height, and each slider gets a usable track. **The tooltip is no",
    "longer the browser's native `title=`**: that waits about a second, which reads as",
